def find_positions(tram, char):
    positions = []
    for r, row in enumerate(tram):
        for c, cell in enumerate(row):
            if cell == char:
                positions.append((r, c))
    return positions

def calculate_distances(point, positions):
    distances = []
    for pos in positions:
        distance = math.sqrt((pos[0] - point[0]) ** 2 + (pos[1] - point[1]) ** 2)
        distances.append((distance, pos))
    return distances

def solve_tram_problem(R, C, tram):
    passengers = find_positions(tram, 'X')
    seats = find_positions(tram, 'L')

    explosions = 0
    seated_passengers = set()

    while passengers:
        explosion_occurred = False
        for passenger in passengers[:]:
            if passenger in seated_passengers:
                continue
            distances_to_seats = calculate_distances(passenger, seats)
            distances_to_seats.sort()

            if not distances_to_seats:
                # No more seats available
                return explosions

            closest_seat_distance, closest_seat = distances_to_seats[0]
            equally_close_seats = [pos for dist, pos in distances_to_seats if dist == closest_seat_distance]

            if len(equally_close_seats) == 1:
                # One closest seat, sit there
                tram[closest_seat[0]][closest_seat[1]] = 'X'
                seated_passengers.add(passenger)
                passengers.remove(passenger)
            else:
                # Explosion occurs
                explosion_occurred = True
                for eq_seat in equally_close_seats:
                    tram[eq_seat[0]][eq_seat[1]] = '.'
                    if eq_seat in seats:
                        seats.remove(eq_seat)
                for eq_passenger in equally_close_seats:
                    if eq_passenger in passengers:
                        passengers.remove(eq_passenger)

            if explosion_occurred:
                explosions += 1
                break

    return explosions

def main():
    R, C, tram = read_input()
    result = solve_tram_problem(R, C, tram)
    print(result)

if __name__ == "__main__":
