def count_explosions(R, C, grid):
    def euclidean_distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def get_neighbors(r, c):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                yield (nr, nc)

    passengers = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 'X']
    seats = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 'L']
    explosions = 0
    seated = set()

    while passengers:
        queue = deque()
        visited = set()
        for p in passengers:
            if p not in seated:
                queue.append((p, [p]))  # (current_position, path_taken)
                visited.add(p)

        exploded = False
        while queue and not exploded:
            current, path = queue.popleft()
            if current in seated:
                continue
            closest_seat = min((s for s in seats if s not in seated), key=lambda s: euclidean_distance(current, s))
            min_distance = euclidean_distance(current, closest_seat)
            next_positions = [p for p in get_neighbors(*current) if p not in visited]

            for next_pos in next_positions:
                if next_pos in seats and next_pos == closest_seat:
                    seated.add(next_pos)
                    passengers.remove(current)
                    exploded = True
                    break
                elif next_pos in seats and euclidean_distance(next_pos, closest_seat) <= min_distance:
                    continue
                queue.append((next_pos, path + [next_pos]))
                visited.add(next_pos)

        if not exploded:
            explosions += 1
            exploding_positions = set(p for p in passengers if euclidean_distance(p, closest_seat) == min_distance)
            passengers = [p for p in passengers if p not in exploding_positions]
            seats = [s for s in seats if s not in exploding_positions]

    return explosions

